  private final class Bridge { @JavascriptInterface public void capture(String text){try{JSONObject page=new JSONObject(text);worker.execute(()->importPage(page));}catch(Exception x){main.post(()->Toast.makeText(MainActivity.this,"Р В РЎСљР В Р’Вµ Р РЋРЎвЂњР В РўвЂР В Р’В°Р В Р’В»Р В РЎвЂўР РЋР С“Р РЋР Р‰ Р В РЎвЂ”Р РЋР вЂљР В РЎвЂўР РЋРІР‚РЋР В РЎвЂР РЋРІР‚С™Р В Р’В°Р РЋРІР‚С™Р РЋР Р‰ Р РЋР С“Р РЋРІР‚С™Р РЋР вЂљР В Р’В°Р В Р вЂ¦Р В РЎвЂР РЋРІР‚В Р РЋРЎвЂњ",Toast.LENGTH_LONG).show());}} }
  private void importPage(JSONObject page){HttpURLConnection c=null;try{String html=page.optString("html","");if(html.length()<10||html.length()>2000000)throw new Exception("Р В Р Р‹Р РЋРІР‚С™Р РЋР вЂљР В Р’В°Р В Р вЂ¦Р В РЎвЂР РЋРІР‚В Р В Р’В° Р В РЎвЂ”Р РЋРЎвЂњР РЋР С“Р РЋРІР‚С™Р В Р’В°Р РЋР РЏ Р В РЎвЂР В Р’В»Р В РЎвЂ Р РЋР С“Р В Р’В»Р В РЎвЂР РЋРІвЂљВ¬Р В РЎвЂќР В РЎвЂўР В РЎВ Р В Р’В±Р В РЎвЂўР В Р’В»Р РЋР Р‰Р РЋРІвЂљВ¬Р В Р’В°Р РЋР РЏ");String cookie=android.webkit.CookieManager.getInstance().getCookie(API_ORIGIN);if(cookie==null||!cookie.contains("__Host-msavdo_admin="))throw new Exception("Р В Р Р‹Р В Р вЂ¦Р В Р’В°Р РЋРІР‚РЋР В Р’В°Р В Р’В»Р В Р’В° Р В Р вЂ Р В РЎвЂўР В РІвЂћвЂ“Р В РўвЂР В РЎвЂР РЋРІР‚С™Р В Р’Вµ Р РЋРІР‚РЋР В Р’ВµР РЋР вЂљР В Р’ВµР В Р’В· Telegram");JSONObject b=new JSONObject();b.put("html_code",html);b.put("original_link",page.optString("url",""));b.put("manual_title",page.optString("title",""));b.put("weight_kg",0.5);b.put("delivery_type","order");b.put("save_to_catalog",true);c=(HttpURLConnection)new URL(API_URL).openConnection();c.setRequestMethod("POST");c.setConnectTimeout(20000);c.setReadTimeout(90000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");c.setRequestProperty("Cookie",cookie);byte[] data=b.toString().getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(data.length);try(OutputStream o=c.getOutputStream()){o.write(data);}int code=c.getResponseCode();InputStream in=code>=400?c.getErrorStream():c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);JSONObject r=new JSONObject(out.toString("UTF-8"));if(code<200||code>=300||!r.optBoolean("success"))throw new Exception(r.optString("error",r.optString("message","Р В РЎвЂєР РЋРІвЂљВ¬Р В РЎвЂР В Р’В±Р В РЎвЂќР В Р’В° Р В РЎвЂР В РЎВР В РЎвЂ”Р В РЎвЂўР РЋР вЂљР РЋРІР‚С™Р В Р’В° HTTP "+code)));String title=r.optJSONObject("product")==null?"Р В РЎС›Р В РЎвЂўР В Р вЂ Р В Р’В°Р РЋР вЂљ":r.optJSONObject("product").optString("title","Р В РЎС›Р В РЎвЂўР В Р вЂ Р В Р’В°Р РЋР вЂљ");main.post(()->{status.setText("Р В Р’В§Р В Р’ВµР РЋР вЂљР В Р вЂ¦Р В РЎвЂўР В Р вЂ Р В РЎвЂР В РЎвЂќ Р В РўвЂР В РЎвЂўР В Р’В±Р В Р’В°Р В Р вЂ Р В Р’В»Р В Р’ВµР В Р вЂ¦: "+title);Toast.makeText(MainActivity.this,"Р В РІР‚СњР В РЎвЂўР В Р’В±Р В Р’В°Р В Р вЂ Р В Р’В»Р В Р’ВµР В Р вЂ¦: "+title,Toast.LENGTH_LONG).show();queue.poll();next.setEnabled(!queue.isEmpty());if(!queue.isEmpty())main.postDelayed(this::openNext,1400);else auto=false;});}catch(Exception x){String m=x.getMessage()==null?"Р В РЎвЂєР РЋРІвЂљВ¬Р В РЎвЂР В Р’В±Р В РЎвЂќР В Р’В° Р В РЎвЂР В РЎВР В РЎвЂ”Р В РЎвЂўР РЋР вЂљР РЋРІР‚С™Р В Р’В°":x.getMessage();main.post(()->{status.setText(m);Toast.makeText(MainActivity.this,m,Toast.LENGTH_LONG).show();auto=false;});}finally{if(c!=null)c.disconnect();}}
